/* ---------------------------------------------------------------------- */
/*  SMALL UI PRIMITIVES                                                    */
/* ---------------------------------------------------------------------- */
function Pill({ children, tone = "neutral" }) {
  const tones = {
    neutral: { bg: C.highlight, fg: C.navy },
    green: { bg: "#E7F1E1", fg: "#4C7A3B" },
    amber: { bg: "#FBF0DD", fg: "#9A6B1E" },
    navy: { bg: C.navy, fg: C.white },
  };
  const t = tones[tone];
  return (
    <span
      className="inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-xs font-semibold"
      style={{ background: t.bg, color: t.fg }}
    >
      {children}
    </span>
  );
}

function StatusPill({ status }) {
  if (status === "Deployed") return <Pill tone="green"><CheckCircle2 size={12} /> Deployed</Pill>;
  if (status === "In progress") return <Pill tone="amber"><Clock size={12} /> In progress</Pill>;
  return <Pill tone="neutral"><FileText size={12} /> Proposal review</Pill>;
}

function SectorTag({ sector }) {
  const meta = SECTOR_META[sector] || SECTOR_META.Water;
  const Icon = meta.icon;
  return (
    <span
      className="inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-semibold"
      style={{ background: `${meta.color}1A`, color: meta.color }}
    >
      <Icon size={12} /> {sector}
    </span>
  );
}

