function Header({ tab, setTab, notifOpen, setNotifOpen, unreadCount }) {
  const tabs = [
    { id: "overview", label: "Overview" },
    { id: "universities", label: "Universities" },
    { id: "collaboration", label: "Collaboration Hub" },
  ];
  return (
    <header
      className="sticky top-0 z-20 border-b"
      style={{ background: C.white, borderColor: "#E7EDF2" }}
    >
      <div className="mx-auto flex max-w-7xl items-center gap-6 px-6 py-3">
        <div className="flex items-center gap-2.5">
          <img src={LOGO_DATA_URI} alt="CivicLink" className="h-8 w-8 object-contain" />
          <div>
            <p className="text-[15px] font-extrabold leading-none" style={{ color: C.navy }}>CivicLink</p>
            <p className="text-[10px] font-medium leading-none mt-1" style={{ color: C.textSecondary }}>Industry Partner Console</p>
          </div>
        </div>

        <nav className="flex flex-1 items-center gap-1">
          {tabs.map((t) => (
            <button
              key={t.id}
              onClick={() => setTab(t.id)}
              className="rounded-lg px-3.5 py-2 text-sm font-semibold transition-colors"
              style={{
                background: tab === t.id ? C.navy : "transparent",
                color: tab === t.id ? C.white : C.textSecondary,
              }}
            >
              {t.label}
            </button>
          ))}
        </nav>

        <div className="hidden items-center gap-2 rounded-lg px-3 py-2 md:flex" style={{ background: C.bg }}>
          <Search size={15} color={C.textSecondary} />
          <input
            placeholder="Search projects, universities…"
            className="w-48 bg-transparent text-sm outline-none placeholder:text-[13px]"
            style={{ color: C.textPrimary }}
          />
        </div>

        <div className="relative">
          <button
            onClick={() => setNotifOpen((v) => !v)}
            className="relative flex h-9 w-9 items-center justify-center rounded-full"
            style={{ background: C.bg }}
          >
            <Bell size={16} color={C.navy} />
            {unreadCount > 0 && (
              <span
                className="absolute -right-0.5 -top-0.5 flex h-4 w-4 items-center justify-center rounded-full text-[9px] font-bold text-white"
                style={{ background: "#C2635A" }}
              >
                {unreadCount}
              </span>
            )}
          </button>
          {notifOpen && (
            <div
              className="absolute right-0 mt-2 w-80 rounded-xl border p-2 shadow-lg"
              style={{ background: C.white, borderColor: "#E7EDF2" }}
            >
              <p className="px-2 py-1.5 text-xs font-bold uppercase tracking-wide" style={{ color: C.textSecondary }}>
                Notifications
              </p>
              {NOTIFICATIONS.map((n, i) => (
                <div key={i} className="flex items-start gap-2 rounded-lg px-2 py-2 hover:bg-slate-50">
                  <span
                    className="mt-1.5 h-1.5 w-1.5 shrink-0 rounded-full"
                    style={{ background: n.unread ? C.teal : "transparent" }}
                  />
                  <div>
                    <p className="text-[13px] font-medium" style={{ color: C.textPrimary }}>{n.text}</p>
                    <p className="text-[11px]" style={{ color: C.textSecondary }}>{n.time}</p>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        <div className="flex items-center gap-2 rounded-full pl-1 pr-3 py-1" style={{ background: C.bg }}>
          <div
            className="flex h-7 w-7 items-center justify-center rounded-full text-xs font-bold text-white"
            style={{ background: C.teal }}
          >
            TS
          </div>
          <span className="text-xs font-semibold" style={{ color: C.textPrimary }}>Tata Steel Foundation</span>
        </div>
      </div>
    </header>
  );
}

